 * @param side        'LONG' | 'SHORT'
 * @returns           止损价
 */
calculateDynamicStopLoss(
  entryPrice: number,
  atr: number,
  side: 'LONG' | 'SHORT' = 'LONG',
): number {
  const offset = atr * this.config.atrStopMultiplier;

  if (side === 'LONG') {
    const stopLoss = entryPrice - offset;
    log.info(

